<script setup lang="ts">
// the written campaign, as the Dungeon Master's own book
import { computed, ref, watch } from 'vue'
import { app, game, gs, script, runScript, travelTo, nextSitting, stage, setSettings, stageScene } from '../session'
import { rich } from './rich'
import { ABILITY_NAME, SKILLS, SKILL_NAME, type Ability, type Skill } from '../rules/base'
const book = computed(() => (void gs.value, script())); const now = computed(() => Math.max(0, book.value.findIndex(c => c.now))); const at = ref(now.value); watch(now, v => at.value = v); const ch = computed(() => book.value[at.value]); const open = ref(''); const KIND: Record<string, string> = { npc: 'Person', scene: 'Scene', fight: 'Fight', boss: 'Boss', trial: 'Trial', puzzle: 'Riddle' }; const sk = (s?: string) => !s ? '' : s in SKILLS ? SKILL_NAME[s as Skill] : ABILITY_NAME[s as Ability] ?? s
const groups = computed(() => { const L = ch.value?.blocks ?? []; const by = new Map<string, typeof L>(); for (const b of L) { const k = b.here ? 'Here' : b.place || 'Elsewhere'; by.set(k, [...(by.get(k) ?? []), b]) } return [...by].sort((a, b) => +(b[0] === 'Here') - +(a[0] === 'Here')) }); const roads = computed(() => (gs.value?.camp?.mod?.list ?? []) as { key: string; name: string; here: boolean }[]); const clean = (t: string) => t.replace(/%who/g, 'someone').replace(/%party/g, 'the company'); const fx = (f?: string[]) => f?.length ? f.join(', ') : ''
const go = (b: any) => { if (!b.where) return; const g = game.value!; if (!g.view.flat) g.setView('iso'); g.centerOn(b.where.x, b.where.z, g.nav.levelOf(b.where.x, b.where.y, b.where.z)) }; const scene = computed(() => (gs.value as any)?.scene); const over = computed(() => gs.value?.camp?.mod?.over)
</script>
<template><div v-if="ch" class="sc"><nav class="nums"><button v-for="(c, i) in book" :key="i" :class="{ on: at === i, done: c.done }" :aria-label="`Sitting ${i + 1}: ${c.title}`" @click="at = i">{{ i + 1 }}</button></nav><h2>{{ ch.title }}</h2><p v-if="over" class="now">The campaign is over: {{ over }}</p><p v-else-if="ch.now" class="now">You are in this sitting.</p>
  <div class="box"><p v-html="rich(clean(ch.read))" /><button class="btn sm" @click="stage?.read(clean(ch.read))">Read aloud</button></div><p class="dm"><b>For you.</b> {{ ch.dm }}</p><p v-if="ch.goal" class="dm"><b>Aim.</b> {{ ch.goal }}</p>
  <div v-if="scene" class="live"><b>{{ scene.name }}</b> is before the table.<button class="btn sm" @click="stageScene('close')">Close it</button></div>
  <div class="row wrap" style="gap:3px;margin:8px 0"><button v-for="r in roads" :key="r.key" class="btn sm" :class="{ on: r.here }" :disabled="r.here" @click="travelTo(r.key)">{{ r.name }}</button><button v-if="ch.now && !over" class="btn sm primary" @click="nextSitting">{{ at + 1 < book.length ? 'End this sitting' : 'End the campaign' }}</button></div>
  <button class="opt" :class="{ on: gs?.set.autoScenes }" @click="setSettings({ autoScenes: !gs?.set.autoScenes })"><i class="tick" /><span>Scenes begin by themselves when the heroes arrive</span></button>
  <template v-for="g in groups" :key="g[0]"><span class="cap">{{ g[0] }}</span><article v-for="b in g[1]" :key="b.key" :class="{ done: b.done, no: !b.on, open: open === b.key }"><header @click="open = open === b.key ? '' : b.key"><i>{{ KIND[b.b.kind] }}</i><b class="cut">{{ b.b.name }}</b><em v-if="!b.on">not yet</em><em v-else-if="b.done">done</em></header>
    <div v-if="open === b.key" class="in"><p v-if="b.b.look" class="muted">{{ b.b.role }}, {{ b.b.look }}</p><p v-if="b.b.say || b.b.hi" class="aloud" v-html="rich(clean(b.b.say || b.b.hi || ''))" /><p v-if="b.b.foes" class="muted">{{ b.b.foes }}<template v-if="b.b.threat">. {{ b.b.threat }}</template></p>
      <div class="row wrap" style="gap:3px"><button v-if="b.b.say" class="btn sm" @click="runScript(b.key, 'read')">Read aloud</button><button v-if="b.where" class="btn sm" @click="go(b)">Look there</button><template v-if="b.here"><button v-if="['scene', 'trial', 'puzzle'].includes(b.b.kind) || b.b.opts.length" class="btn sm primary" @click="runScript(b.key, 'show')">Put it to the table</button><button v-if="['fight', 'boss'].includes(b.b.kind)" class="btn sm" @click="runScript(b.key, 'bring')">Set them out</button><button v-if="['fight', 'boss'].includes(b.b.kind)" class="btn sm primary" @click="runScript(b.key, 'fight')">Start the fight</button></template><button v-if="b.b.win" class="btn sm" @click="runScript(b.key, 'win')">They win</button><button v-if="b.b.lose" class="btn sm" @click="runScript(b.key, 'lose')">They lose</button><button class="btn sm quiet" @click="runScript(b.key, 'done')">{{ b.done ? 'Not done after all' : 'Mark done' }}</button></div>
      <div v-for="(o, i) in b.b.opts" :key="i" class="o"><b>{{ o.t }}<template v-if="o.skill"> ({{ sk(o.skill) }} {{ o.dc }})</template><template v-if="o.cost"> ({{ o.cost }} gold)</template></b><p><span v-html="rich(clean(o.ok.text))" /><small v-if="fx(o.ok.fx)">{{ fx(o.ok.fx) }}</small></p><p v-if="o.fail" class="f"><span v-html="rich(clean(o.fail.text))" /><small v-if="fx(o.fail.fx)">{{ fx(o.fail.fx) }}</small></p><div class="row" style="gap:3px"><button class="btn sm" @click="runScript(b.key, 'ok', i)">{{ o.fail ? 'It works' : 'They do' }}</button><button v-if="o.fail" class="btn sm" @click="runScript(b.key, 'fail', i)">It fails</button></div></div>
      <div v-for="(t, i) in b.b.topics ?? []" :key="'t' + i" class="o"><b>{{ t.label }}<template v-if="t.check"> ({{ sk(t.check.skill) }} {{ t.check.dc }})</template></b><p><span v-html="rich(clean(t.out.text))" /><small v-if="fx(t.out.fx)">{{ fx(t.out.fx) }}</small></p><button class="btn sm" @click="runScript(b.key, 'topic', i)">Say it</button></div>
      <p v-for="(t, i) in b.b.skills ?? []" :key="'k' + i" class="o">{{ sk(t.skill) }} {{ t.dc }}: {{ t.t }}</p><p v-if="b.b.answers?.length" class="o"><b>Answers</b> {{ b.b.answers.join(', ') }}</p><p v-for="(t, i) in b.b.hints ?? []" :key="'h' + i" class="o">{{ sk(t.skill) }} {{ t.dc }}: {{ t.t }}</p><p v-if="b.b.win" class="o"><b>If they win</b> {{ clean(b.b.win.text) }}<small v-if="fx(b.b.win.fx)">{{ fx(b.b.win.fx) }}</small></p><p v-if="b.b.lose" class="o"><b>If they lose</b> {{ clean(b.b.lose.text) }}<small v-if="fx(b.b.lose.fx)">{{ fx(b.b.lose.fx) }}</small></p></div></article></template></div></template>
<style scoped>.nums{display:flex;gap:2px;margin-bottom:12px}.nums button{flex:1;text-align:center;font:700 21px/34px var(--serif);background:var(--navy2);color:var(--tx2)}.nums .done{color:var(--tx3);text-decoration:line-through}.nums .on{background:var(--spot);color:var(--on-spot);text-decoration:none}h2{font-size:30px}.now{color:var(--spot);margin:3px 0 0;font-weight:500}.box{background:var(--paper);color:var(--ink);padding:12px 15px;margin:10px 0;font:400 17.5px/1.32 var(--serif)}.box p{white-space:pre-line}.box .btn{background:var(--paper2);color:var(--ink);font-family:var(--ui)}.dm{font-size:16px;margin-bottom:7px}.live{background:var(--spot);color:var(--on-spot);padding:6px 8px 6px 12px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}.live .btn{margin-left:auto;background:#0003}
article{border-bottom:1px solid var(--line2)}article header{display:flex;align-items:baseline;gap:10px;padding:7px 0;cursor:pointer}article header:hover{color:var(--spot)}header i{font-style:normal;font-size:14.5px;color:var(--tx2);width:52px;flex:none}header b{font:700 19px/1.1 var(--serif);flex:1}header em{font-style:normal;font-size:14.5px;color:var(--tx3)}.done header b,.no header b{color:var(--tx3)}.open header b{color:var(--spot)}.in{padding:0 0 14px;border-left:4px solid var(--spot);padding-left:13px;margin-bottom:8px}.aloud{font-size:17.5px}.o{border-top:1px solid var(--line);padding:8px 0;margin:8px 0 0;font-size:16px;line-height:1.32}.o>b{font-weight:600;display:block}.o p{margin:2px 0 6px}.o .f{color:var(--tx2)}.o .f::before{content:'Fails: '}small{display:block;color:var(--spot);font-size:14.5px}</style>
